// Sử dụng Promise.allSettled để tránh fail toàn bộ batch job
interface BatchResult {
  successful: string[];
  failed: string[];
}

async function syncAccounts(accountIds: string[]): Promise<BatchResult> {
  const results = await Promise.allSettled(
    accountIds.map(id => thirdPartyApi.sync(id))
  );

  return results.reduce<BatchResult>((acc, res, idx) => {
    if (res.status === 'fulfilled') acc.successful.push(accountIds[idx]);
    else acc.failed.push(accountIds[idx]);
    return acc;
  }, { successful: [], failed: [] });
}

// Xử lý transaction với async/await rõ ràng và an toàn
async function transferFunds(fromId: string, toId: string, amount: number) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await accountRepo.debit(client, fromId, amount);
    await accountRepo.credit(client, toId, amount);
    await client.query('COMMIT');
  } catch (error) {
    await client.query('ROLLBACK');
    throw error; // Re-throw để upper layer ghi log hoặc xử lý HTTP code
  } finally {
    client.release(); // Luôn release connection về pool
  }
}

