import { redisClient } from './redis';

const inflightRequests = new Map<string, Promise<any>>();

export async function getCachedDataSingleFlight(key: string, fetchDbFn: () => Promise<any>) {
  const cached = await redisClient.get(key);
  if (cached) return JSON.parse(cached);

  // Nếu đang có 1 request khác đi query DB cho chính key này, ta chia sẻ cùng Promise
  if (inflightRequests.has(key)) {
    return inflightRequests.get(key);
  }

  const promise = (async () => {
    try {
      const freshData = await fetchDbFn();
      const jitterTtl = 300 + Math.floor(Math.random() * 60); // Jitter chống Avalanche
      await redisClient.set(key, JSON.stringify(freshData), { EX: jitterTtl });
      return freshData;
    } finally {
      inflightRequests.delete(key);
    }
  })();

  inflightRequests.set(key, promise);
  return promise;
}

